	"font" text,
	"decoration_pack" text,
	"sparkles" boolean DEFAULT false NOT NULL,
	"location" text,
	"currently" text,
	"music_url" text,
	"music_title" text,
	"music_artist" text,
	"banner_media_id" uuid,
