	"top_friends_size" smallint DEFAULT 8 NOT NULL,
	"top_friends_visibility" "paldora"."room_top_friends_visibility" DEFAULT 'friends' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "rooms_configuration_version_check" CHECK ("paldora"."rooms"."configuration_version" = 1),
	CONSTRAINT "rooms_theme_preset_check" CHECK ("paldora"."rooms"."theme_preset" in ('obsidian_gold', 'cream_paper', 'lavender_dream', 'ocean_glow', 'daisy_day', 'neon_night', 'y2k_glitter', 'dark_academia', 'frutiger_aero', 'tumblr_2014', 'retro_windows', 'cyberpunk', 'minimal_editorial', 'polaroid_scrapbook')),
	CONSTRAINT "rooms_accent_check" CHECK ("paldora"."rooms"."accent" is null or "paldora"."rooms"."accent" in ('gold', 'lavender', 'ocean', 'daisy', 'pink', 'emerald', 'cyan', 'crimson')),
	CONSTRAINT "rooms_font_check" CHECK ("paldora"."rooms"."font" is null or "paldora"."rooms"."font" in ('editorial', 'modern', 'rounded', 'mono', 'handwritten')),
	CONSTRAINT "rooms_decoration_pack_check" CHECK ("paldora"."rooms"."decoration_pack" is null or "paldora"."rooms"."decoration_pack" in ('none', 'stars', 'flowers', 'stickers', 'tape', 'pixels')),
	CONSTRAINT "rooms_location_length_check" CHECK ("paldora"."rooms"."location" is null or char_length("paldora"."rooms"."location") between 1 and 120),
	CONSTRAINT "rooms_currently_length_check" CHECK ("paldora"."rooms"."currently" is null or char_length("paldora"."rooms"."currently") between 1 and 240),
	CONSTRAINT "rooms_music_url_check" CHECK ("paldora"."rooms"."music_url" is null or ("paldora"."rooms"."music_url" like 'https://%' and char_length("paldora"."rooms"."music_url") <= 2048 and "paldora"."rooms"."music_url" !~ '\s' and "paldora"."rooms"."music_url" !~ '^https://[^/?#]*@')),
	CONSTRAINT "rooms_music_title_length_check" CHECK ("paldora"."rooms"."music_title" is null or char_length("paldora"."rooms"."music_title") between 1 and 120),
	CONSTRAINT "rooms_music_artist_length_check" CHECK ("paldora"."rooms"."music_artist" is null or char_length("paldora"."rooms"."music_artist") between 1 and 120),
	CONSTRAINT "rooms_music_text_requires_url_check" CHECK ("paldora"."rooms"."music_url" is not null or ("paldora"."rooms"."music_title" is null and "paldora"."rooms"."music_artist" is null)),
	CONSTRAINT "rooms_top_friends_size_check" CHECK ("paldora"."rooms"."top_friends_size" in (4, 8, 12))
);
