-- The database twin of hiddenByBlock/isBlockedBetween (packages/database
-- blocks.ts, ADR 013): true when either person has blocked the other. Same
-- predicate; a test checks that the two agree.
CREATE FUNCTION "paldora"."is_blocked_between"(first_user uuid, second_user uuid) RETURNS boolean
LANGUAGE sql STABLE PARALLEL SAFE
AS $$
  select exists (
    select 1 from "paldora"."user_blocks"
    where ("blocker_id" = first_user and "blocked_id" = second_user)
       or ("blocker_id" = second_user and "blocked_id" = first_user)
  )
$$;--> statement-breakpoint
-- A Room keeps its owner and creation time. Every write moves updated_at
-- forward by at least a microsecond, so two saves never share a version
-- (the expectedUpdatedAt stale check compares it exactly).
CREATE FUNCTION "paldora"."rooms_touch"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW."user_id" IS DISTINCT FROM OLD."user_id"
     OR NEW."created_at" IS DISTINCT FROM OLD."created_at" THEN
    RAISE EXCEPTION 'rooms_immutable_columns'
      USING ERRCODE = '23000', CONSTRAINT = 'rooms_immutable_columns';
  END IF;
  NEW."updated_at" := greatest(clock_timestamp(), OLD."updated_at" + interval '1 microsecond');
  RETURN NEW;
END
$$;--> statement-breakpoint
CREATE TRIGGER "rooms_touch"
BEFORE UPDATE ON "paldora"."rooms"
FOR EACH ROW EXECUTE FUNCTION "paldora"."rooms_touch"();--> statement-breakpoint
-- Lowering the Top Friends size removes the entries that no longer fit, in
-- the same statement.
CREATE FUNCTION "paldora"."rooms_trim_top_friends"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  DELETE FROM "paldora"."room_top_friends"
  WHERE "room_user_id" = NEW."user_id" AND "position" >= NEW."top_friends_size";
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE TRIGGER "rooms_trim_top_friends"
AFTER UPDATE OF "top_friends_size" ON "paldora"."rooms"
FOR EACH ROW WHEN (NEW."top_friends_size" < OLD."top_friends_size")
EXECUTE FUNCTION "paldora"."rooms_trim_top_friends"();--> statement-breakpoint
-- At commit, a Room has all seven widget rows or none. With the primary key
-- and the type check, seven rows means each type exactly once. A cascade
-- from rooms leaves none, which passes.
CREATE FUNCTION "paldora"."room_widgets_complete_set"() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  room uuid;
  widget_count integer;
BEGIN
  FOREACH room IN ARRAY ARRAY[
    CASE WHEN TG_OP <> 'DELETE' THEN NEW."room_user_id" END,
    CASE WHEN TG_OP <> 'INSERT' THEN OLD."room_user_id" END
  ] LOOP
    CONTINUE WHEN room IS NULL;
    SELECT count(*) INTO widget_count
    FROM "paldora"."room_widgets" WHERE "room_user_id" = room;
    IF widget_count NOT IN (0, 7) THEN
      RAISE EXCEPTION 'room_widgets_incomplete'
        USING ERRCODE = '23000', CONSTRAINT = 'room_widgets_incomplete';
    END IF;
  END LOOP;
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER "room_widgets_complete_set"
AFTER INSERT OR UPDATE OR DELETE ON "paldora"."room_widgets"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "paldora"."room_widgets_complete_set"();--> statement-breakpoint
-- The final authority on who can be a Top Friend: an accepted friend of the
-- owner, active, with no block either way, at a position below the Room's
-- size. FOR SHARE on the Room row serializes with a size change, and FOR
-- SHARE on the friendship row serializes with an unfriend or block (both
-- delete that row): whichever commits first, no stale entry survives,
-- because the removal triggers below run after this row is visible.
CREATE FUNCTION "paldora"."room_top_friends_insert_guard"() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  room_size smallint;
BEGIN
  SELECT "top_friends_size" INTO room_size
  FROM "paldora"."rooms" WHERE "user_id" = NEW."room_user_id"
  FOR SHARE;
  IF room_size IS NOT NULL AND NEW."position" >= room_size THEN
    RAISE EXCEPTION 'top_friend_position_out_of_range'
      USING ERRCODE = '23000', CONSTRAINT = 'top_friend_position_out_of_range';
  END IF;
  PERFORM 1 FROM "paldora"."friendships"
  WHERE "user_low_id" = least(NEW."room_user_id", NEW."friend_user_id")
    AND "user_high_id" = greatest(NEW."room_user_id", NEW."friend_user_id")
    AND "status" = 'accepted'
  FOR SHARE;
  IF NOT FOUND
     OR "paldora"."is_blocked_between"(NEW."room_user_id", NEW."friend_user_id")
     OR NOT EXISTS (
       SELECT 1 FROM "paldora"."users"
       WHERE "id" = NEW."friend_user_id" AND "status" = 'active'
     ) THEN
    RAISE EXCEPTION 'top_friend_not_eligible'
      USING ERRCODE = '23000', CONSTRAINT = 'top_friend_not_eligible';
  END IF;
  RETURN NEW;
END
$$;--> statement-breakpoint
CREATE TRIGGER "room_top_friends_insert_guard"
BEFORE INSERT OR UPDATE OF "room_user_id", "friend_user_id", "position" ON "paldora"."room_top_friends"
FOR EACH ROW EXECUTE FUNCTION "paldora"."room_top_friends_insert_guard"();--> statement-breakpoint
-- Removes a pair's Top Friend entries in both directions. Shared by the
-- unfriend and block triggers.
CREATE FUNCTION "paldora"."remove_pair_top_friends"(first_user uuid, second_user uuid) RETURNS void
LANGUAGE sql
AS $$
  delete from "paldora"."room_top_friends"
  where ("room_user_id" = first_user and "friend_user_id" = second_user)
     or ("room_user_id" = second_user and "friend_user_id" = first_user)
$$;--> statement-breakpoint
-- Unfriending (the row is deleted) or any move away from accepted removes
-- the pair from each other's Top Friends, in the same transaction, for
-- every code path (services, admin tools, cascades, direct SQL).
CREATE FUNCTION "paldora"."friendships_remove_top_friends"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD."status" = 'accepted'
     AND (TG_OP = 'DELETE' OR NEW."status" IS DISTINCT FROM 'accepted') THEN
    PERFORM "paldora"."remove_pair_top_friends"(OLD."user_low_id", OLD."user_high_id");
  END IF;
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE TRIGGER "friendships_remove_top_friends"
AFTER DELETE OR UPDATE OF "status" ON "paldora"."friendships"
FOR EACH ROW EXECUTE FUNCTION "paldora"."friendships_remove_top_friends"();--> statement-breakpoint
-- A block in either direction removes the pair from each other's Top
-- Friends. Blocking already deletes the friendship today; this keeps the
-- invariant for any path that inserts a block without touching it.
CREATE FUNCTION "paldora"."user_blocks_remove_top_friends"() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  PERFORM "paldora"."remove_pair_top_friends"(NEW."blocker_id", NEW."blocked_id");
  RETURN NULL;
END
$$;--> statement-breakpoint
CREATE TRIGGER "user_blocks_remove_top_friends"
AFTER INSERT ON "paldora"."user_blocks"
FOR EACH ROW EXECUTE FUNCTION "paldora"."user_blocks_remove_top_friends"();
